INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-themes-b2-01-01', 'lesson-themes-b2-01', 1, 'word', 'climate', 'clima', '/ˈklaɪmət/', NULL, '[]'::jsonb, '[{"surface":"climate","pos":"noun","ipa":"/ˈklaɪmət/","gloss":"clima"}]'::jsonb, 'Climate change affects every country.', 'A mudança climática afeta todos os países.'),
  ('unit-themes-b2-01-02', 'lesson-themes-b2-01', 2, 'word', 'pollution', 'poluição', '/pəˈluːʃən/', NULL, '[]'::jsonb, '[{"surface":"pollution","pos":"noun","ipa":"/pəˈluːʃən/","gloss":"poluição"}]'::jsonb, 'Air pollution is a serious problem in big cities.', 'A poluição do ar é um problema sério nas grandes cidades.'),
  ('unit-themes-b2-01-03', 'lesson-themes-b2-01', 3, 'word', 'renewable', 'renovável', '/rɪˈnuːəbəl/', NULL, '[]'::jsonb, '[{"surface":"renewable","pos":"adjective","ipa":"/rɪˈnuːəbəl/","gloss":"renovável"}]'::jsonb, 'Solar power is a renewable source of energy.', 'A energia solar é uma fonte renovável de energia.'),
  ('unit-themes-b2-01-04', 'lesson-themes-b2-01', 4, 'word', 'emissions', 'emissões', '/ɪˈmɪʃənz/', NULL, '[]'::jsonb, '[{"surface":"emissions","pos":"noun","ipa":"/ɪˈmɪʃənz/","gloss":"emissões"}]'::jsonb, 'The company promised to cut its emissions.', 'A empresa prometeu reduzir suas emissões.'),
  ('unit-themes-b2-01-05', 'lesson-themes-b2-01', 5, 'word', 'wildlife', 'vida selvagem', '/ˈwaɪldlaɪf/', NULL, '[]'::jsonb, '[{"surface":"wildlife","pos":"noun","ipa":"/ˈwaɪldlaɪf/","gloss":"vida selvagem"}]'::jsonb, 'The park protects local wildlife.', 'O parque protege a vida selvagem local.'),
  ('unit-themes-b2-01-06', 'lesson-themes-b2-01', 6, 'word', 'habitat', 'habitat', '/ˈhæbɪtæt/', NULL, '[]'::jsonb, '[{"surface":"habitat","pos":"noun","ipa":"/ˈhæbɪtæt/","gloss":"habitat"}]'::jsonb, 'Many animals are losing their habitat.', 'Muitos animais estão perdendo seu habitat.'),
  ('unit-themes-b2-01-07', 'lesson-themes-b2-01', 7, 'word', 'drought', 'seca', '/draʊt/', NULL, '[]'::jsonb, '[{"surface":"drought","pos":"noun","ipa":"/draʊt/","gloss":"seca"}]'::jsonb, 'The drought lasted three years.', 'A seca durou três anos.'),
  ('unit-themes-b2-01-08', 'lesson-themes-b2-01', 8, 'word', 'flood', 'enchente', '/flʌd/', NULL, '[]'::jsonb, '[{"surface":"flood","pos":"noun","ipa":"/flʌd/","gloss":"enchente"}]'::jsonb, 'The flood destroyed several homes.', 'A enchente destruiu várias casas.'),
  ('unit-themes-b2-01-09', 'lesson-themes-b2-01', 9, 'word', 'recycling', 'reciclagem', '/ˌriːˈsaɪklɪŋ/', NULL, '[]'::jsonb, '[{"surface":"recycling","pos":"noun","ipa":"/ˌriːˈsaɪklɪŋ/","gloss":"reciclagem"}]'::jsonb, 'Recycling saves energy and raw materials.', 'A reciclagem economiza energia e matéria-prima.'),
  ('unit-themes-b2-01-10', 'lesson-themes-b2-01', 10, 'word', 'landfill', 'aterro sanitário', '/ˈlændfɪl/', NULL, '[]'::jsonb, '[{"surface":"landfill","pos":"noun","ipa":"/ˈlændfɪl/","gloss":"aterro sanitário"}]'::jsonb, 'Most of our trash ends up in a landfill.', 'A maior parte do nosso lixo acaba num aterro sanitário.'),
  ('unit-themes-b2-01-11', 'lesson-themes-b2-01', 11, 'word', 'sustainable', 'sustentável', '/səˈsteɪnəbəl/', NULL, '[]'::jsonb, '[{"surface":"sustainable","pos":"adjective","ipa":"/səˈsteɪnəbəl/","gloss":"sustentável"}]'::jsonb, 'We need a more sustainable way of living.', 'Precisamos de um jeito de viver mais sustentável.'),
  ('unit-themes-b2-01-12', 'lesson-themes-b2-01', 12, 'word', 'fossil', 'fóssil', '/ˈfɑːsəl/', NULL, '[]'::jsonb, '[{"surface":"fossil","pos":"adjective","ipa":"/ˈfɑːsəl/","gloss":"fóssil"}]'::jsonb, 'Burning fossil fuels warms the planet.', 'Queimar combustíveis fósseis aquece o planeta.'),
  ('unit-themes-b2-01-13', 'lesson-themes-b2-01', 13, 'word', 'carbon', 'carbono', '/ˈkɑːrbən/', NULL, '[]'::jsonb, '[{"surface":"carbon","pos":"noun","ipa":"/ˈkɑːrbən/","gloss":"carbono"}]'::jsonb, 'Trees absorb carbon from the air.', 'As árvores absorvem carbono do ar.'),
  ('unit-themes-b2-01-14', 'lesson-themes-b2-01', 14, 'word', 'conservation', 'conservação', '/ˌkɑːnsərˈveɪʃən/', NULL, '[]'::jsonb, '[{"surface":"conservation","pos":"noun","ipa":"/ˌkɑːnsərˈveɪʃən/","gloss":"conservação"}]'::jsonb, 'Conservation projects need public support.', 'Projetos de conservação precisam de apoio público.'),
  ('unit-themes-b2-01-15', 'lesson-themes-b2-01', 15, 'word', 'species', 'espécie', '/ˈspiːʃiːz/', '"Species" tem a mesma forma no singular e no plural.', '[]'::jsonb, '[{"surface":"species","pos":"noun","ipa":"/ˈspiːʃiːz/","gloss":"espécie"}]'::jsonb, 'Thousands of species are in danger.', 'Milhares de espécies estão em perigo.'),
  ('unit-themes-b2-01-16', 'lesson-themes-b2-01', 16, 'word', 'resources', 'recursos', '/ˈriːsɔːrsɪz/', NULL, '[]'::jsonb, '[{"surface":"resources","pos":"noun","ipa":"/ˈriːsɔːrsɪz/","gloss":"recursos"}]'::jsonb, 'Water is a limited resource.', 'A água é um recurso limitado.'),
  ('unit-themes-b2-01-17', 'lesson-themes-b2-01', 17, 'word', 'waste', 'desperdício, lixo', '/weɪst/', NULL, '[]'::jsonb, '[{"surface":"waste","pos":"verb","ipa":"/weɪst/","gloss":"desperdiçar"}]'::jsonb, 'We throw away too much food waste.', 'Jogamos fora comida demais.'),
  ('unit-themes-b2-01-18', 'lesson-themes-b2-01', 18, 'word', 'greenhouse', 'estufa', '/ˈɡriːnˌhaʊs/', NULL, '[]'::jsonb, '[{"surface":"greenhouse","pos":"noun","ipa":"/ˈɡriːnˌhaʊs/","gloss":"estufa"}]'::jsonb, 'The greenhouse effect warms the Earth.', 'O efeito estufa aquece a Terra.'),
  ('unit-themes-b2-01-19', 'lesson-themes-b2-01', 19, 'word', 'ecosystem', 'ecossistema', '/ˈiːkoʊsɪstəm/', NULL, '[]'::jsonb, '[{"surface":"ecosystem","pos":"noun","ipa":"/ˈiːkoʊsɪstəm/","gloss":"ecossistema"}]'::jsonb, 'A small change can damage the whole ecosystem.', 'Uma pequena mudança pode prejudicar todo o ecossistema.'),
  ('unit-themes-b2-01-20', 'lesson-themes-b2-01', 20, 'word', 'deforestation', 'desmatamento', '/diːˌfɔːrɪˈsteɪʃən/', NULL, '[]'::jsonb, '[{"surface":"deforestation","pos":"noun","ipa":"/diːˌfɔːrɪˈsteɪʃən/","gloss":"desmatamento"}]'::jsonb, 'Deforestation is destroying large areas of forest.', 'O desmatamento está destruindo grandes áreas de floresta.')
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-themes-b2-02-01', 'lesson-themes-b2-02', 1, 'word', 'software', 'programa, software', '/ˈsɔːftwɛr/', '"Software" não tem plural.', '[]'::jsonb, '[{"surface":"software","pos":"noun","ipa":"/ˈsɔːftwɛr/","gloss":"software"}]'::jsonb, 'The software updates itself every week.', 'O programa se atualiza toda semana.'),
  ('unit-themes-b2-02-02', 'lesson-themes-b2-02', 2, 'word', 'algorithm', 'algoritmo', '/ˈælɡərɪðəm/', NULL, '[]'::jsonb, '[{"surface":"algorithm","pos":"noun","ipa":"/ˈælɡərɪðəm/","gloss":"algoritmo"}]'::jsonb, 'The algorithm decides which videos you see.', 'O algoritmo decide quais vídeos você vê.'),
  ('unit-themes-b2-02-03', 'lesson-themes-b2-02', 3, 'word', 'device', 'dispositivo', '/dɪˈvaɪs/', NULL, '[]'::jsonb, '[{"surface":"device","pos":"noun","ipa":"/dɪˈvaɪs/","gloss":"dispositivo"}]'::jsonb, 'Turn off all devices during the flight.', 'Desligue todos os dispositivos durante o voo.'),
  ('unit-themes-b2-02-04', 'lesson-themes-b2-02', 4, 'word', 'network', 'rede', '/ˈnɛtwɜːrk/', NULL, '[]'::jsonb, '[{"surface":"network","pos":"noun","ipa":"/ˈnɛtwɜːrk/","gloss":"rede"}]'::jsonb, 'The office network is down again.', 'A rede do escritório caiu de novo.'),
  ('unit-themes-b2-02-05', 'lesson-themes-b2-02', 5, 'word', 'encryption', 'criptografia', '/ɪnˈkrɪpʃən/', NULL, '[]'::jsonb, '[{"surface":"encryption","pos":"noun","ipa":"/ɪnˈkrɪpʃən/","gloss":"criptografia"}]'::jsonb, 'Encryption protects your messages.', 'A criptografia protege suas mensagens.'),
  ('unit-themes-b2-02-06', 'lesson-themes-b2-02', 6, 'word', 'privacy', 'privacidade', '/ˈpraɪvəsi/', NULL, '[]'::jsonb, '[{"surface":"privacy","pos":"noun","ipa":"/ˈpraɪvəsi/","gloss":"privacidade"}]'::jsonb, 'Many people worry about online privacy.', 'Muitas pessoas se preocupam com a privacidade online.'),
  ('unit-themes-b2-02-07', 'lesson-themes-b2-02', 7, 'word', 'automation', 'automação', '/ˌɔːtəˈmeɪʃən/', NULL, '[]'::jsonb, '[{"surface":"automation","pos":"noun","ipa":"/ˌɔːtəˈmeɪʃən/","gloss":"automação"}]'::jsonb, 'Automation will change many jobs.', 'A automação vai mudar muitas profissões.'),
  ('unit-themes-b2-02-08', 'lesson-themes-b2-02', 8, 'word', 'innovation', 'inovação', '/ˌɪnəˈveɪʃən/', NULL, '[]'::jsonb, '[{"surface":"innovation","pos":"noun","ipa":"/ˌɪnəˈveɪʃən/","gloss":"inovação"}]'::jsonb, 'Innovation keeps the company ahead of its rivals.', 'A inovação mantém a empresa à frente dos rivais.'),
  ('unit-themes-b2-02-09', 'lesson-themes-b2-02', 9, 'word', 'upgrade', 'atualização, melhoria', '/ˈʌpɡreɪd/', NULL, '[]'::jsonb, '[{"surface":"upgrade","pos":"noun","ipa":"/ˈʌpɡreɪd/","gloss":"atualização, melhoria"}]'::jsonb, 'I need to upgrade my phone.', 'Preciso trocar meu celular por um melhor.'),
  ('unit-themes-b2-02-10', 'lesson-themes-b2-02', 10, 'word', 'bandwidth', 'largura de banda', '/ˈbændwɪdθ/', NULL, '[]'::jsonb, '[{"surface":"bandwidth","pos":"noun","ipa":"/ˈbændwɪdθ/","gloss":"largura de banda"}]'::jsonb, 'We do not have enough bandwidth for video calls.', 'Não temos largura de banda suficiente para chamadas de vídeo.'),
  ('unit-themes-b2-02-11', 'lesson-themes-b2-02', 11, 'word', 'cybersecurity', 'segurança digital', '/ˌsaɪbərsɪˈkjʊrəti/', NULL, '[]'::jsonb, '[{"surface":"cybersecurity","pos":"noun","ipa":"/ˌsaɪbərsɪˈkjʊrəti/","gloss":"segurança digital"}]'::jsonb, 'Cybersecurity is a priority for banks.', 'A segurança digital é prioridade para os bancos.'),
  ('unit-themes-b2-02-12', 'lesson-themes-b2-02', 12, 'word', 'interface', 'interface', '/ˈɪntərfeɪs/', NULL, '[]'::jsonb, '[{"surface":"interface","pos":"noun","ipa":"/ˈɪntərfeɪs/","gloss":"interface"}]'::jsonb, 'The interface is clean and easy to use.', 'A interface é limpa e fácil de usar.'),
  ('unit-themes-b2-02-13', 'lesson-themes-b2-02', 13, 'word', 'prototype', 'protótipo', '/ˈproʊtətaɪp/', NULL, '[]'::jsonb, '[{"surface":"prototype","pos":"noun","ipa":"/ˈproʊtətaɪp/","gloss":"protótipo"}]'::jsonb, 'The team built a prototype in two weeks.', 'A equipe construiu um protótipo em duas semanas.'),
  ('unit-themes-b2-02-14', 'lesson-themes-b2-02', 14, 'word', 'database', 'banco de dados', '/ˈdeɪtəbeɪs/', NULL, '[]'::jsonb, '[{"surface":"database","pos":"noun","ipa":"/ˈdeɪtəbeɪs/","gloss":"banco de dados"}]'::jsonb, 'All customer data is stored in a database.', 'Todos os dados dos clientes ficam num banco de dados.'),
  ('unit-themes-b2-02-15', 'lesson-themes-b2-02', 15, 'word', 'platform', 'plataforma', '/ˈplætfɔːrm/', NULL, '[]'::jsonb, '[{"surface":"platform","pos":"noun","ipa":"/ˈplætfɔːrm/","gloss":"plataforma"}]'::jsonb, 'The platform has millions of users.', 'A plataforma tem milhões de usuários.'),
  ('unit-themes-b2-02-16', 'lesson-themes-b2-02', 16, 'word', 'wireless', 'sem fio', '/ˈwaɪərləs/', NULL, '[]'::jsonb, '[{"surface":"wireless","pos":"adjective","ipa":"/ˈwaɪərləs/","gloss":"sem fio"}]'::jsonb, 'I prefer wireless headphones.', 'Prefiro fones de ouvido sem fio.'),
  ('unit-themes-b2-02-17', 'lesson-themes-b2-02', 17, 'word', 'download', 'baixar', '/ˈdaʊnloʊd/', NULL, '[]'::jsonb, '[{"surface":"download","pos":"verb","ipa":"/ˈdaʊnloʊd/","gloss":"baixar"}]'::jsonb, 'You can download the app for free.', 'Você pode baixar o aplicativo de graça.'),
  ('unit-themes-b2-02-18', 'lesson-themes-b2-02', 18, 'word', 'malfunction', 'defeito, falha', '/mælˈfʌŋkʃən/', NULL, '[]'::jsonb, '[{"surface":"malfunction","pos":"noun","ipa":"/mælˈfʌŋkʃən/","gloss":"defeito, falha"}]'::jsonb, 'A malfunction caused the delay.', 'Uma falha causou o atraso.'),
  ('unit-themes-b2-02-19', 'lesson-themes-b2-02', 19, 'word', 'breakthrough', 'avanço importante', '/ˈbreɪkθruː/', NULL, '[]'::jsonb, '[{"surface":"breakthrough","pos":"noun","ipa":"/ˈbreɪkθruː/","gloss":"avanço importante"}]'::jsonb, 'Scientists announced a breakthrough in battery design.', 'Cientistas anunciaram um avanço no projeto de baterias.'),
  ('unit-themes-b2-02-20', 'lesson-themes-b2-02', 20, 'word', 'digital', 'digital', '/ˈdɪdʒɪtəl/', NULL, '[]'::jsonb, '[{"surface":"digital","pos":"adjective","ipa":"/ˈdɪdʒɪtəl/","gloss":"digital"}]'::jsonb, 'Digital skills are essential today.', 'Habilidades digitais são essenciais hoje.')
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-themes-b2-03-01', 'lesson-themes-b2-03', 1, 'word', 'inflation', 'inflação', '/ɪnˈfleɪʃən/', NULL, '[]'::jsonb, '[{"surface":"inflation","pos":"noun","ipa":"/ɪnˈfleɪʃən/","gloss":"inflação"}]'::jsonb, 'Inflation makes everyday items more expensive.', 'A inflação deixa os itens do dia a dia mais caros.'),
  ('unit-themes-b2-03-02', 'lesson-themes-b2-03', 2, 'word', 'recession', 'recessão', '/rɪˈsɛʃən/', NULL, '[]'::jsonb, '[{"surface":"recession","pos":"noun","ipa":"/rɪˈsɛʃən/","gloss":"recessão"}]'::jsonb, 'The country entered a recession last year.', 'O país entrou em recessão no ano passado.'),
  ('unit-themes-b2-03-03', 'lesson-themes-b2-03', 3, 'word', 'tax', 'imposto', '/tæks/', NULL, '[]'::jsonb, '[{"surface":"tax","pos":"noun","ipa":"/tæks/","gloss":"imposto"}]'::jsonb, 'The government raised the tax on fuel.', 'O governo aumentou o imposto sobre combustíveis.'),
  ('unit-themes-b2-03-04', 'lesson-themes-b2-03', 4, 'word', 'investment', 'investimento', '/ɪnˈvɛstmənt/', NULL, '[]'::jsonb, '[{"surface":"investment","pos":"noun","ipa":"/ɪnˈvɛstmənt/","gloss":"investimento"}]'::jsonb, 'Education is a long-term investment.', 'A educação é um investimento de longo prazo.'),
  ('unit-themes-b2-03-05', 'lesson-themes-b2-03', 5, 'word', 'savings', 'economias, poupança', '/ˈseɪvɪŋz/', '"Savings" costuma vir no plural.', '[]'::jsonb, '[{"surface":"savings","pos":"noun","ipa":"/ˈseɪvɪŋz/","gloss":"economias"}]'::jsonb, 'She spent all her savings on the trip.', 'Ela gastou todas as economias na viagem.'),
  ('unit-themes-b2-03-06', 'lesson-themes-b2-03', 6, 'word', 'salary', 'salário', '/ˈsæləri/', NULL, '[]'::jsonb, '[{"surface":"salary","pos":"noun","ipa":"/ˈsæləri/","gloss":"salário"}]'::jsonb, 'His salary is higher than mine.', 'O salário dele é maior que o meu.'),
  ('unit-themes-b2-03-07', 'lesson-themes-b2-03', 7, 'word', 'unemployment', 'desemprego', '/ˌʌnɪmˈplɔɪmənt/', NULL, '[]'::jsonb, '[{"surface":"unemployment","pos":"noun","ipa":"/ˌʌnɪmˈplɔɪmənt/","gloss":"desemprego"}]'::jsonb, 'Unemployment rose slightly in March.', 'O desemprego subiu um pouco em março.'),
  ('unit-themes-b2-03-08', 'lesson-themes-b2-03', 8, 'word', 'trade', 'comércio', '/treɪd/', NULL, '[]'::jsonb, '[{"surface":"trade","pos":"noun","ipa":"/treɪd/","gloss":"comércio"}]'::jsonb, 'Trade between the two countries is growing.', 'O comércio entre os dois países está crescendo.'),
  ('unit-themes-b2-03-09', 'lesson-themes-b2-03', 9, 'word', 'currency', 'moeda', '/ˈkɜːrənsi/', NULL, '[]'::jsonb, '[{"surface":"currency","pos":"noun","ipa":"/ˈkɜːrənsi/","gloss":"moeda"}]'::jsonb, 'The local currency lost value.', 'A moeda local perdeu valor.'),
  ('unit-themes-b2-03-10', 'lesson-themes-b2-03', 10, 'word', 'wealth', 'riqueza', '/wɛlθ/', NULL, '[]'::jsonb, '[{"surface":"wealth","pos":"noun","ipa":"/wɛlθ/","gloss":"riqueza"}]'::jsonb, 'Wealth is not distributed equally.', 'A riqueza não é distribuída igualmente.'),
  ('unit-themes-b2-03-11', 'lesson-themes-b2-03', 11, 'word', 'poverty', 'pobreza', '/ˈpɑːvərti/', NULL, '[]'::jsonb, '[{"surface":"poverty","pos":"noun","ipa":"/ˈpɑːvərti/","gloss":"pobreza"}]'::jsonb, 'Poverty affects millions of families.', 'A pobreza afeta milhões de famílias.'),
  ('unit-themes-b2-03-12', 'lesson-themes-b2-03', 12, 'word', 'subsidy', 'subsídio', '/ˈsʌbsədi/', NULL, '[]'::jsonb, '[{"surface":"subsidy","pos":"noun","ipa":"/ˈsʌbsədi/","gloss":"subsídio"}]'::jsonb, 'Farmers receive a subsidy from the state.', 'Os agricultores recebem um subsídio do Estado.'),
  ('unit-themes-b2-03-13', 'lesson-themes-b2-03', 13, 'word', 'shortage', 'escassez, falta', '/ˈʃɔːrtɪdʒ/', NULL, '[]'::jsonb, '[{"surface":"shortage","pos":"noun","ipa":"/ˈʃɔːrtɪdʒ/","gloss":"escassez, falta"}]'::jsonb, 'There is a shortage of skilled workers.', 'Há falta de trabalhadores qualificados.'),
  ('unit-themes-b2-03-14', 'lesson-themes-b2-03', 14, 'word', 'supply', 'oferta, fornecimento', '/səˈplaɪ/', NULL, '[]'::jsonb, '[{"surface":"supply","pos":"noun","ipa":"/səˈplaɪ/","gloss":"oferta, fornecimento"}]'::jsonb, 'Supply and demand set the price.', 'Oferta e demanda definem o preço.'),
  ('unit-themes-b2-03-15', 'lesson-themes-b2-03', 15, 'word', 'mortgage', 'financiamento imobiliário', '/ˈmɔːrɡɪdʒ/', NULL, '[]'::jsonb, '[{"surface":"mortgage","pos":"noun","ipa":"/ˈmɔːrɡɪdʒ/","gloss":"financiamento imobiliário"}]'::jsonb, 'They paid off their mortgage after twenty years.', 'Eles quitaram o financiamento da casa depois de vinte anos.'),
  ('unit-themes-b2-03-16', 'lesson-themes-b2-03', 16, 'word', 'economy', 'economia', '/ɪˈkɑːnəmi/', NULL, '[]'::jsonb, '[{"surface":"economy","pos":"noun","ipa":"/ɪˈkɑːnəmi/","gloss":"economia"}]'::jsonb, 'The economy grew by two percent.', 'A economia cresceu dois por cento.'),
  ('unit-themes-b2-03-17', 'lesson-themes-b2-03', 17, 'word', 'growth', 'crescimento', '/ɡroʊθ/', NULL, '[]'::jsonb, '[{"surface":"growth","pos":"noun","ipa":"/ɡroʊθ/","gloss":"crescimento"}]'::jsonb, 'Economic growth slowed this year.', 'O crescimento econômico desacelerou neste ano.'),
  ('unit-themes-b2-03-18', 'lesson-themes-b2-03', 18, 'word', 'wages', 'salários, pagamento', '/ˈweɪdʒɪz/', NULL, '[]'::jsonb, '[{"surface":"wages","pos":"noun","ipa":"/ˈweɪdʒɪz/","gloss":"salários, pagamento"}]'::jsonb, 'Wages have not kept up with prices.', 'Os salários não acompanharam os preços.'),
  ('unit-themes-b2-03-19', 'lesson-themes-b2-03', 19, 'word', 'consumers', 'consumidores', '/kənˈsuːmərz/', NULL, '[]'::jsonb, '[{"surface":"consumers","pos":"noun","ipa":"/kənˈsuːmərz/","gloss":"consumidores"}]'::jsonb, 'Consumers are spending less.', 'Os consumidores estão gastando menos.'),
  ('unit-themes-b2-03-20', 'lesson-themes-b2-03', 20, 'word', 'expenses', 'despesas', '/ɪkˈspɛnsɪz/', NULL, '[]'::jsonb, '[{"surface":"expenses","pos":"noun","ipa":"/ɪkˈspɛnsɪz/","gloss":"despesas"}]'::jsonb, 'Rent is our biggest monthly expense.', 'O aluguel é nossa maior despesa mensal.')
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-themes-b2-04-01', 'lesson-themes-b2-04', 1, 'word', 'symptom', 'sintoma', '/ˈsɪmptəm/', NULL, '[]'::jsonb, '[{"surface":"symptom","pos":"noun","ipa":"/ˈsɪmptəm/","gloss":"sintoma"}]'::jsonb, 'Fever is a common symptom of the flu.', 'Febre é um sintoma comum da gripe.'),
  ('unit-themes-b2-04-02', 'lesson-themes-b2-04', 2, 'word', 'diagnosis', 'diagnóstico', '/ˌdaɪəɡˈnoʊsɪs/', NULL, '[]'::jsonb, '[{"surface":"diagnosis","pos":"noun","ipa":"/ˌdaɪəɡˈnoʊsɪs/","gloss":"diagnóstico"}]'::jsonb, 'The doctor confirmed the diagnosis.', 'O médico confirmou o diagnóstico.'),
  ('unit-themes-b2-04-03', 'lesson-themes-b2-04', 3, 'word', 'treatment', 'tratamento', '/ˈtriːtmənt/', NULL, '[]'::jsonb, '[{"surface":"treatment","pos":"noun","ipa":"/ˈtriːtmənt/","gloss":"tratamento"}]'::jsonb, 'The treatment lasts about six weeks.', 'O tratamento dura cerca de seis semanas.'),
  ('unit-themes-b2-04-04', 'lesson-themes-b2-04', 4, 'word', 'prescription', 'receita médica', '/prɪˈskrɪpʃən/', NULL, '[]'::jsonb, '[{"surface":"prescription","pos":"noun","ipa":"/prɪˈskrɪpʃən/","gloss":"receita médica"}]'::jsonb, 'You need a prescription for this medicine.', 'Você precisa de receita para este remédio.'),
  ('unit-themes-b2-04-05', 'lesson-themes-b2-04', 5, 'word', 'recovery', 'recuperação', '/rɪˈkʌvəri/', NULL, '[]'::jsonb, '[{"surface":"recovery","pos":"noun","ipa":"/rɪˈkʌvəri/","gloss":"recuperação"}]'::jsonb, 'Her recovery was faster than expected.', 'A recuperação dela foi mais rápida que o esperado.'),
  ('unit-themes-b2-04-06', 'lesson-themes-b2-04', 6, 'word', 'chronic', 'crônico', '/ˈkrɑːnɪk/', NULL, '[]'::jsonb, '[{"surface":"chronic","pos":"adjective","ipa":"/ˈkrɑːnɪk/","gloss":"crônico"}]'::jsonb, 'He suffers from chronic back pain.', 'Ele sofre de dor crônica nas costas.'),
  ('unit-themes-b2-04-07', 'lesson-themes-b2-04', 7, 'word', 'infection', 'infecção', '/ɪnˈfɛkʃən/', NULL, '[]'::jsonb, '[{"surface":"infection","pos":"noun","ipa":"/ɪnˈfɛkʃən/","gloss":"infecção"}]'::jsonb, 'The wound got an infection.', 'O ferimento infeccionou.'),
  ('unit-themes-b2-04-08', 'lesson-themes-b2-04', 8, 'word', 'vaccine', 'vacina', '/vækˈsiːn/', NULL, '[]'::jsonb, '[{"surface":"vaccine","pos":"noun","ipa":"/vækˈsiːn/","gloss":"vacina"}]'::jsonb, 'The vaccine protects against several diseases.', 'A vacina protege contra várias doenças.'),
  ('unit-themes-b2-04-09', 'lesson-themes-b2-04', 9, 'word', 'nutrition', 'nutrição', '/nuˈtrɪʃən/', NULL, '[]'::jsonb, '[{"surface":"nutrition","pos":"noun","ipa":"/nuˈtrɪʃən/","gloss":"nutrição"}]'::jsonb, 'Good nutrition starts with fresh food.', 'Boa nutrição começa com comida fresca.'),
  ('unit-themes-b2-04-10', 'lesson-themes-b2-04', 10, 'word', 'wellbeing', 'bem-estar', '/ˈwɛlbiːɪŋ/', NULL, '[]'::jsonb, '[{"surface":"wellbeing","pos":"noun","ipa":"/ˈwɛlbiːɪŋ/","gloss":"bem-estar"}]'::jsonb, 'Sleep is essential for your wellbeing.', 'O sono é essencial para o seu bem-estar.'),
  ('unit-themes-b2-04-11', 'lesson-themes-b2-04', 11, 'word', 'exercise', 'exercício', '/ˈɛksərsaɪz/', NULL, '[]'::jsonb, '[{"surface":"exercise","pos":"verb","ipa":"/ˈɛksərsaɪz/","gloss":"exercitar-se"}]'::jsonb, 'Regular exercise reduces stress.', 'O exercício regular reduz o estresse.'),
  ('unit-themes-b2-04-12', 'lesson-themes-b2-04', 12, 'word', 'stress', 'estresse', '/strɛs/', NULL, '[]'::jsonb, '[{"surface":"stress","pos":"noun","ipa":"/strɛs/","gloss":"estresse"}]'::jsonb, 'Too much stress can make you sick.', 'Estresse demais pode te deixar doente.'),
  ('unit-themes-b2-04-13', 'lesson-themes-b2-04', 13, 'word', 'therapy', 'terapia', '/ˈθɛrəpi/', NULL, '[]'::jsonb, '[{"surface":"therapy","pos":"noun","ipa":"/ˈθɛrəpi/","gloss":"terapia"}]'::jsonb, 'Therapy helped him deal with anxiety.', 'A terapia o ajudou a lidar com a ansiedade.'),
  ('unit-themes-b2-04-14', 'lesson-themes-b2-04', 14, 'word', 'allergy', 'alergia', '/ˈælərdʒi/', NULL, '[]'::jsonb, '[{"surface":"allergy","pos":"noun","ipa":"/ˈælərdʒi/","gloss":"alergia"}]'::jsonb, 'I have an allergy to peanuts.', 'Tenho alergia a amendoim.'),
  ('unit-themes-b2-04-15', 'lesson-themes-b2-04', 15, 'word', 'immune', 'imunológico, imune', '/ɪˈmjuːn/', NULL, '[]'::jsonb, '[{"surface":"immune","pos":"adjective","ipa":"/ɪˈmjuːn/","gloss":"imunológico, imune"}]'::jsonb, 'A healthy diet supports the immune system.', 'Uma dieta saudável apoia o sistema imunológico.'),
  ('unit-themes-b2-04-16', 'lesson-themes-b2-04', 16, 'word', 'dosage', 'dose', '/ˈdoʊsɪdʒ/', NULL, '[]'::jsonb, '[{"surface":"dosage","pos":"noun","ipa":"/ˈdoʊsɪdʒ/","gloss":"dose"}]'::jsonb, 'Follow the dosage on the label.', 'Siga a dose indicada na embalagem.'),
  ('unit-themes-b2-04-17', 'lesson-themes-b2-04', 17, 'word', 'screening', 'exame preventivo', '/ˈskriːnɪŋ/', NULL, '[]'::jsonb, '[{"surface":"screening","pos":"noun","ipa":"/ˈskriːnɪŋ/","gloss":"exame preventivo"}]'::jsonb, 'Early screening can save lives.', 'O exame preventivo precoce pode salvar vidas.'),
  ('unit-themes-b2-04-18', 'lesson-themes-b2-04', 18, 'word', 'fatigue', 'cansaço extremo', '/fəˈtiːɡ/', NULL, '[]'::jsonb, '[{"surface":"fatigue","pos":"noun","ipa":"/fəˈtiːɡ/","gloss":"cansaço extremo"}]'::jsonb, 'Fatigue is a common side effect.', 'O cansaço extremo é um efeito colateral comum.'),
  ('unit-themes-b2-04-19', 'lesson-themes-b2-04', 19, 'word', 'hygiene', 'higiene', '/ˈhaɪdʒiːn/', NULL, '[]'::jsonb, '[{"surface":"hygiene","pos":"noun","ipa":"/ˈhaɪdʒiːn/","gloss":"higiene"}]'::jsonb, 'Good hygiene prevents many illnesses.', 'Boa higiene previne muitas doenças.'),
  ('unit-themes-b2-04-20', 'lesson-themes-b2-04', 20, 'word', 'mental', 'mental', '/ˈmɛntəl/', NULL, '[]'::jsonb, '[{"surface":"mental","pos":"adjective","ipa":"/ˈmɛntəl/","gloss":"mental"}]'::jsonb, 'Mental health deserves more attention.', 'A saúde mental merece mais atenção.')
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-themes-b2-05-01', 'lesson-themes-b2-05', 1, 'word', 'headline', 'manchete', '/ˈhɛdlaɪn/', NULL, '[]'::jsonb, '[{"surface":"headline","pos":"noun","ipa":"/ˈhɛdlaɪn/","gloss":"manchete"}]'::jsonb, 'The headline was misleading.', 'A manchete era enganosa.'),
  ('unit-themes-b2-05-02', 'lesson-themes-b2-05', 2, 'word', 'journalist', 'jornalista', '/ˈdʒɜːrnəlɪst/', NULL, '[]'::jsonb, '[{"surface":"journalist","pos":"noun","ipa":"/ˈdʒɜːrnəlɪst/","gloss":"jornalista"}]'::jsonb, 'The journalist interviewed three witnesses.', 'O jornalista entrevistou três testemunhas.'),
  ('unit-themes-b2-05-03', 'lesson-themes-b2-05', 3, 'word', 'broadcast', 'transmitir, transmissão', '/ˈbrɔːdkæst/', NULL, '[]'::jsonb, '[{"surface":"broadcast","pos":"verb","ipa":"/ˈbrɔːdkæst/","gloss":"transmitir, transmissão"}]'::jsonb, 'The match will be broadcast live.', 'A partida será transmitida ao vivo.'),
  ('unit-themes-b2-05-04', 'lesson-themes-b2-05', 4, 'word', 'audience', 'público, audiência', '/ˈɔːdiəns/', NULL, '[]'::jsonb, '[{"surface":"audience","pos":"noun","ipa":"/ˈɔːdiəns/","gloss":"público, audiência"}]'::jsonb, 'The show attracts a young audience.', 'O programa atrai um público jovem.'),
  ('unit-themes-b2-05-05', 'lesson-themes-b2-05', 5, 'word', 'editor', 'editor', '/ˈɛdɪtər/', NULL, '[]'::jsonb, '[{"surface":"editor","pos":"noun","ipa":"/ˈɛdɪtər/","gloss":"editor"}]'::jsonb, 'The editor cut two paragraphs from the article.', 'O editor cortou dois parágrafos da matéria.'),
  ('unit-themes-b2-05-06', 'lesson-themes-b2-05', 6, 'word', 'source', 'fonte', '/sɔːrs/', NULL, '[]'::jsonb, '[{"surface":"source","pos":"noun","ipa":"/sɔːrs/","gloss":"fonte"}]'::jsonb, 'Always check your source before sharing.', 'Sempre confira a fonte antes de compartilhar.'),
  ('unit-themes-b2-05-07', 'lesson-themes-b2-05', 7, 'word', 'bias', 'viés', '/ˈbaɪəs/', NULL, '[]'::jsonb, '[{"surface":"bias","pos":"noun","ipa":"/ˈbaɪəs/","gloss":"viés"}]'::jsonb, 'The article shows a clear bias.', 'A matéria mostra um viés evidente.'),
  ('unit-themes-b2-05-08', 'lesson-themes-b2-05', 8, 'word', 'censorship', 'censura', '/ˈsɛnsərʃɪp/', NULL, '[]'::jsonb, '[{"surface":"censorship","pos":"noun","ipa":"/ˈsɛnsərʃɪp/","gloss":"censura"}]'::jsonb, 'Censorship limits freedom of expression.', 'A censura limita a liberdade de expressão.'),
  ('unit-themes-b2-05-09', 'lesson-themes-b2-05', 9, 'word', 'viral', 'viral', '/ˈvaɪrəl/', NULL, '[]'::jsonb, '[{"surface":"viral","pos":"adjective","ipa":"/ˈvaɪrəl/","gloss":"viral"}]'::jsonb, 'The video went viral overnight.', 'O vídeo viralizou da noite para o dia.'),
  ('unit-themes-b2-05-10', 'lesson-themes-b2-05', 10, 'word', 'subscription', 'assinatura', '/səbˈskrɪpʃən/', NULL, '[]'::jsonb, '[{"surface":"subscription","pos":"noun","ipa":"/səbˈskrɪpʃən/","gloss":"assinatura"}]'::jsonb, 'I canceled my subscription to the newspaper.', 'Cancelei minha assinatura do jornal.'),
  ('unit-themes-b2-05-11', 'lesson-themes-b2-05', 11, 'word', 'coverage', 'cobertura', '/ˈkʌvərɪdʒ/', NULL, '[]'::jsonb, '[{"surface":"coverage","pos":"noun","ipa":"/ˈkʌvərɪdʒ/","gloss":"cobertura"}]'::jsonb, 'The coverage of the event was excellent.', 'A cobertura do evento foi excelente.'),
  ('unit-themes-b2-05-12', 'lesson-themes-b2-05', 12, 'word', 'documentary', 'documentário', '/ˌdɑːkjəˈmɛntəri/', NULL, '[]'::jsonb, '[{"surface":"documentary","pos":"noun","ipa":"/ˌdɑːkjəˈmɛntəri/","gloss":"documentário"}]'::jsonb, 'We watched a documentary about the ocean.', 'Assistimos a um documentário sobre o oceano.'),
  ('unit-themes-b2-05-13', 'lesson-themes-b2-05', 13, 'word', 'tabloid', 'tabloide', '/ˈtæblɔɪd/', NULL, '[]'::jsonb, '[{"surface":"tabloid","pos":"noun","ipa":"/ˈtæblɔɪd/","gloss":"tabloide"}]'::jsonb, 'The tabloid published a false story.', 'O tabloide publicou uma história falsa.'),
  ('unit-themes-b2-05-14', 'lesson-themes-b2-05', 14, 'word', 'column', 'coluna (de jornal)', '/ˈkɑːləm/', NULL, '[]'::jsonb, '[{"surface":"column","pos":"noun","ipa":"/ˈkɑːləm/","gloss":"coluna (de jornal)"}]'::jsonb, 'She writes a weekly column about food.', 'Ela escreve uma coluna semanal sobre comida.'),
  ('unit-themes-b2-05-15', 'lesson-themes-b2-05', 15, 'word', 'podcast', 'podcast', '/ˈpɑːdkæst/', NULL, '[]'::jsonb, '[{"surface":"podcast","pos":"noun","ipa":"/ˈpɑːdkæst/","gloss":"podcast"}]'::jsonb, 'I listen to a podcast on my way to work.', 'Escuto um podcast a caminho do trabalho.'),
  ('unit-themes-b2-05-16', 'lesson-themes-b2-05', 16, 'word', 'influencer', 'influenciador', '/ˈɪnfluənsər/', NULL, '[]'::jsonb, '[{"surface":"influencer","pos":"noun","ipa":"/ˈɪnfluənsər/","gloss":"influenciador"}]'::jsonb, 'The influencer promoted a new brand.', 'O influenciador divulgou uma marca nova.'),
  ('unit-themes-b2-05-17', 'lesson-themes-b2-05', 17, 'word', 'advertising', 'publicidade', '/ˈædvərtaɪzɪŋ/', NULL, '[]'::jsonb, '[{"surface":"advertising","pos":"noun","ipa":"/ˈædvərtaɪzɪŋ/","gloss":"publicidade"}]'::jsonb, 'Advertising shapes what we want to buy.', 'A publicidade molda o que queremos comprar.'),
  ('unit-themes-b2-05-18', 'lesson-themes-b2-05', 18, 'word', 'press', 'imprensa', '/prɛs/', NULL, '[]'::jsonb, '[{"surface":"press","pos":"noun","ipa":"/prɛs/","gloss":"imprensa"}]'::jsonb, 'The press was waiting outside the court.', 'A imprensa esperava do lado de fora do tribunal.'),
  ('unit-themes-b2-05-19', 'lesson-themes-b2-05', 19, 'word', 'rumor', 'boato', '/ˈruːmər/', NULL, '[]'::jsonb, '[{"surface":"rumor","pos":"noun","ipa":"/ˈruːmər/","gloss":"boato"}]'::jsonb, 'That is just a rumor, not a fact.', 'Isso é só um boato, não um fato.'),
  ('unit-themes-b2-05-20', 'lesson-themes-b2-05', 20, 'word', 'opinion', 'opinião', '/əˈpɪnjən/', NULL, '[]'::jsonb, '[{"surface":"opinion","pos":"noun","ipa":"/əˈpɪnjən/","gloss":"opinião"}]'::jsonb, 'The newspaper printed an opinion piece.', 'O jornal publicou um artigo de opinião.')
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-themes-b2-06-01', 'lesson-themes-b2-06', 1, 'word', 'trust', 'confiança', '/trʌst/', NULL, '[]'::jsonb, '[{"surface":"trust","pos":"verb","ipa":"/trʌst/","gloss":"confiar"}]'::jsonb, 'Trust takes years to build.', 'A confiança leva anos para ser construída.'),
  ('unit-themes-b2-06-02', 'lesson-themes-b2-06', 2, 'word', 'loyalty', 'lealdade', '/ˈlɔɪəlti/', NULL, '[]'::jsonb, '[{"surface":"loyalty","pos":"noun","ipa":"/ˈlɔɪəlti/","gloss":"lealdade"}]'::jsonb, 'Loyalty matters more than money to him.', 'Para ele, lealdade importa mais que dinheiro.'),
  ('unit-themes-b2-06-03', 'lesson-themes-b2-06', 3, 'word', 'jealousy', 'ciúme', '/ˈdʒɛləsi/', NULL, '[]'::jsonb, '[{"surface":"jealousy","pos":"noun","ipa":"/ˈdʒɛləsi/","gloss":"ciúme"}]'::jsonb, 'Jealousy can ruin a good friendship.', 'O ciúme pode arruinar uma boa amizade.'),
  ('unit-themes-b2-06-04', 'lesson-themes-b2-06', 4, 'word', 'commitment', 'compromisso', '/kəˈmɪtmənt/', NULL, '[]'::jsonb, '[{"surface":"commitment","pos":"noun","ipa":"/kəˈmɪtmənt/","gloss":"compromisso"}]'::jsonb, 'Marriage is a big commitment.', 'O casamento é um grande compromisso.'),
  ('unit-themes-b2-06-05', 'lesson-themes-b2-06', 5, 'word', 'argument', 'discussão, briga', '/ˈɑːrɡjəmənt/', NULL, '[]'::jsonb, '[{"surface":"argument","pos":"noun","ipa":"/ˈɑːrɡjəmənt/","gloss":"argumento"}]'::jsonb, 'We had an argument about money.', 'Tivemos uma discussão por causa de dinheiro.'),
  ('unit-themes-b2-06-06', 'lesson-themes-b2-06', 6, 'word', 'apology', 'pedido de desculpas', '/əˈpɑːlədʒi/', NULL, '[]'::jsonb, '[{"surface":"apology","pos":"noun","ipa":"/əˈpɑːlədʒi/","gloss":"pedido de desculpas"}]'::jsonb, 'He owes her an apology.', 'Ele lhe deve um pedido de desculpas.'),
  ('unit-themes-b2-06-07', 'lesson-themes-b2-06', 7, 'word', 'forgiveness', 'perdão', '/fərˈɡɪvnəs/', NULL, '[]'::jsonb, '[{"surface":"forgiveness","pos":"noun","ipa":"/fərˈɡɪvnəs/","gloss":"perdão"}]'::jsonb, 'Forgiveness is not always easy.', 'Perdoar nem sempre é fácil.'),
  ('unit-themes-b2-06-08', 'lesson-themes-b2-06', 8, 'word', 'support', 'apoio, apoiar', '/səˈpɔːrt/', NULL, '[]'::jsonb, '[{"surface":"support","pos":"verb","ipa":"/səˈpɔːrt/","gloss":"apoiar"}]'::jsonb, 'Her family gave her great support.', 'A família deu muito apoio a ela.'),
  ('unit-themes-b2-06-09', 'lesson-themes-b2-06', 9, 'word', 'companionship', 'companhia', '/kəmˈpænjənʃɪp/', NULL, '[]'::jsonb, '[{"surface":"companionship","pos":"noun","ipa":"/kəmˈpænjənʃɪp/","gloss":"companhia"}]'::jsonb, 'Dogs offer companionship to older people.', 'Os cachorros oferecem companhia a pessoas mais velhas.'),
  ('unit-themes-b2-06-10', 'lesson-themes-b2-06', 10, 'word', 'respect', 'respeito', '/rɪˈspɛkt/', NULL, '[]'::jsonb, '[{"surface":"respect","pos":"noun","ipa":"/rɪˈspɛkt/","gloss":"respeito"}]'::jsonb, 'Every relationship needs respect.', 'Toda relação precisa de respeito.'),
  ('unit-themes-b2-06-11', 'lesson-themes-b2-06', 11, 'word', 'betrayal', 'traição', '/bɪˈtreɪəl/', NULL, '[]'::jsonb, '[{"surface":"betrayal","pos":"noun","ipa":"/bɪˈtreɪəl/","gloss":"traição"}]'::jsonb, 'The betrayal hurt more than the lie.', 'A traição doeu mais que a mentira.'),
  ('unit-themes-b2-06-12', 'lesson-themes-b2-06', 12, 'word', 'affection', 'carinho', '/əˈfɛkʃən/', NULL, '[]'::jsonb, '[{"surface":"affection","pos":"noun","ipa":"/əˈfɛkʃən/","gloss":"carinho"}]'::jsonb, 'She showed her affection with small gestures.', 'Ela demonstrava carinho com pequenos gestos.'),
  ('unit-themes-b2-06-13', 'lesson-themes-b2-06', 13, 'word', 'reliable', 'confiável', '/rɪˈlaɪəbəl/', NULL, '[]'::jsonb, '[{"surface":"reliable","pos":"adjective","ipa":"/rɪˈlaɪəbəl/","gloss":"confiável"}]'::jsonb, 'He is a reliable friend.', 'Ele é um amigo confiável.'),
  ('unit-themes-b2-06-14', 'lesson-themes-b2-06', 14, 'word', 'acquaintance', 'conhecido', '/əˈkweɪntəns/', NULL, '[]'::jsonb, '[{"surface":"acquaintance","pos":"noun","ipa":"/əˈkweɪntəns/","gloss":"conhecido"}]'::jsonb, 'He is more an acquaintance than a friend.', 'Ele é mais um conhecido do que um amigo.'),
  ('unit-themes-b2-06-15', 'lesson-themes-b2-06', 15, 'word', 'mentor', 'mentor', '/ˈmɛntɔːr/', NULL, '[]'::jsonb, '[{"surface":"mentor","pos":"noun","ipa":"/ˈmɛntɔːr/","gloss":"mentor"}]'::jsonb, 'My mentor taught me how to negotiate.', 'Meu mentor me ensinou a negociar.'),
  ('unit-themes-b2-06-16', 'lesson-themes-b2-06', 16, 'word', 'bond', 'vínculo', '/bɑːnd/', NULL, '[]'::jsonb, '[{"surface":"bond","pos":"noun","ipa":"/bɑːnd/","gloss":"vínculo"}]'::jsonb, 'The two sisters have a strong bond.', 'As duas irmãs têm um vínculo forte.'),
  ('unit-themes-b2-06-17', 'lesson-themes-b2-06', 17, 'word', 'empathy', 'empatia', '/ˈɛmpəθi/', NULL, '[]'::jsonb, '[{"surface":"empathy","pos":"noun","ipa":"/ˈɛmpəθi/","gloss":"empatia"}]'::jsonb, 'Empathy helps you understand other people.', 'A empatia ajuda você a entender os outros.'),
  ('unit-themes-b2-06-18', 'lesson-themes-b2-06', 18, 'word', 'distance', 'distância', '/ˈdɪstəns/', NULL, '[]'::jsonb, '[{"surface":"distance","pos":"noun","ipa":"/ˈdɪstəns/","gloss":"distância"}]'::jsonb, 'Distance made the friendship harder.', 'A distância dificultou a amizade.'),
  ('unit-themes-b2-06-19', 'lesson-themes-b2-06', 19, 'word', 'honest', 'sincero', '/ˈɑːnɪst/', NULL, '[]'::jsonb, '[{"surface":"honest","pos":"adjective","ipa":"/ˈɑːnɪst/","gloss":"sincero, honesto"}]'::jsonb, 'I appreciate honest feedback.', 'Valorizo um retorno sincero.'),
  ('unit-themes-b2-06-20', 'lesson-themes-b2-06', 20, 'word', 'patience', 'paciência', '/ˈpeɪʃəns/', NULL, '[]'::jsonb, '[{"surface":"patience","pos":"noun","ipa":"/ˈpeɪʃəns/","gloss":"paciência"}]'::jsonb, 'Raising children takes a lot of patience.', 'Criar filhos exige muita paciência.')
